{
  "findings": [
    {
      "check_id": "CKV_GCP_26",
      "title": "VPC Flow Logs are not enabled",
      "resource": "google_compute_subnetwork.data_subnet",
      "severity": "MEDIUM",
      "explanation": "The subnetwork has no log_config block, preventing collection of network flow telemetry needed for traffic monitoring and incident investigation."
    }
  ],
  "patched_code": "resource "google_compute_subnetwork" "data_subnet" {
  name                     = "hipaa-compliant-patient-portal-subnet-data"
  ip_cidr_range            = "10.0.3.0/24"
  region                   = var.region
  network                  = google_compute_network.hipaa_vpc.id
  private_ip_google_access = true

  log_config {
    aggregation_interval = "INTERVAL_5_SEC"
    flow_sampling        = 1.0
    metadata             = "INCLUDE_ALL_METADATA"
  }
}
",
  "fix_summary": "Enabled VPC Flow Logs for the data subnetwork with full flow sampling and metadata collection to improve network monitoring and incident investigation."
}
